import{_ as l,o as e,c as t,a4 as i}from"./chunks/framework.9tZL7ZIQ.js";const m=JSON.parse('{"title":"托德·康姆斯（Todd W. Combs）","description":"","frontmatter":{},"headers":[],"relativePath":"04_people/托德·康姆斯.md","filePath":"04_people/托德·康姆斯.md"}'),r={name:"04_people/托德·康姆斯.md"};function h(o,a,d,n,s,u){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="托德·康姆斯-todd-w-combs" tabindex="-1">托德·康姆斯（Todd W. Combs） <a class="header-anchor" href="#托德·康姆斯-todd-w-combs" aria-label="Permalink to &quot;托德·康姆斯（Todd W. Combs）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>全名</td><td>Todd W. Combs</td></tr><tr><td>出生</td><td>约1969年</td></tr><tr><td>公司</td><td><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a></td></tr><tr><td>职位</td><td>投资经理</td></tr><tr><td>任期</td><td>2009年至今</td></tr></tbody></table><h2 id="职业生涯" tabindex="-1">职业生涯 <a class="header-anchor" href="#职业生涯" aria-label="Permalink to &quot;职业生涯&quot;">​</a></h2><h3 id="早年经历" tabindex="-1">早年经历 <a class="header-anchor" href="#早年经历" aria-label="Permalink to &quot;早年经历&quot;">​</a></h3><ul><li>早年经历低调，专注于投资研究</li><li>在加入伯克希尔前积累了丰富的投资经验</li></ul><h3 id="对冲基金经历" tabindex="-1">对冲基金经历 <a class="header-anchor" href="#对冲基金经历" aria-label="Permalink to &quot;对冲基金经历&quot;">​</a></h3><ul><li>2009年之前运营对冲基金 <strong>Par Capital Management</strong></li><li>在对冲基金期间建立了独特的投资方法论</li><li>以深入的基本面研究著称</li></ul><h2 id="加入伯克希尔" tabindex="-1">加入伯克希尔 <a class="header-anchor" href="#加入伯克希尔" aria-label="Permalink to &quot;加入伯克希尔&quot;">​</a></h2><h3 id="招聘过程" tabindex="-1">招聘过程 <a class="header-anchor" href="#招聘过程" aria-label="Permalink to &quot;招聘过程&quot;">​</a></h3><ul><li>2009年加入<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a>（先于韦斯勒）</li><li>先由猎头主动联系</li><li>随后与<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>进行面试</li><li>整个招聘过程由<a href="/04_people/阿吉特·贾恩.html">阿吉特·贾恩</a>主导</li></ul><h3 id="初始角色" tabindex="-1">初始角色 <a class="header-anchor" href="#初始角色" aria-label="Permalink to &quot;初始角色&quot;">​</a></h3><ul><li>接手管理约<strong>10亿美元</strong>的股票组合</li><li>初期独立管理个人账户投资</li></ul><h2 id="投资风格" tabindex="-1">投资风格 <a class="header-anchor" href="#投资风格" aria-label="Permalink to &quot;投资风格&quot;">​</a></h2><h3 id="核心特点" tabindex="-1">核心特点 <a class="header-anchor" href="#核心特点" aria-label="Permalink to &quot;核心特点&quot;">​</a></h3><ol><li><strong>与巴菲特互补</strong>：关注巴菲特较少涉足的领域</li><li><strong>偏好小型股</strong>：善于挖掘中小市值投资机会</li><li><strong>深入研究</strong>：重仓前必做详尽的基本面分析</li><li><strong>长期持有</strong>：一旦认定优秀公司，长期持有不频繁交易</li></ol><h3 id="研究深度" tabindex="-1">研究深度 <a class="header-anchor" href="#研究深度" aria-label="Permalink to &quot;研究深度&quot;">​</a></h3><ul><li>对投资标的进行深度尽职调查</li><li>关注公司竞争优势的可持续性</li><li>重视管理层质量和诚信</li></ul><h2 id="代表投资" tabindex="-1">代表投资 <a class="header-anchor" href="#代表投资" aria-label="Permalink to &quot;代表投资&quot;">​</a></h2><h3 id="知名持仓" tabindex="-1">知名持仓 <a class="header-anchor" href="#知名持仓" aria-label="Permalink to &quot;知名持仓&quot;">​</a></h3><ul><li>在<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a>任职期间有多个显著的投资决策</li><li>投资风格与<a href="/04_people/卢·辛普森.html">卢·辛普森</a>有相似之处</li><li>同样注重企业的内在价值和长期潜力</li></ul><h2 id="角色演变" tabindex="-1">角色演变 <a class="header-anchor" href="#角色演变" aria-label="Permalink to &quot;角色演变&quot;">​</a></h2><h3 id="_2010年-接管geico" tabindex="-1">2010年：接管GEICO <a class="header-anchor" href="#_2010年-接管geico" aria-label="Permalink to &quot;2010年：接管GEICO&quot;">​</a></h3><ul><li>开始管理<a href="/03_companies/GEICO.html">GEICO</a>的股票组合</li><li>接管约<strong>30亿美元</strong>的GEICO投资组合</li><li>接替<a href="/04_people/卢·辛普森.html">卢·辛普森</a>的部分职责</li></ul><h3 id="_2011年后-扩大管理范围" tabindex="-1">2011年后：扩大管理范围 <a class="header-anchor" href="#_2011年后-扩大管理范围" aria-label="Permalink to &quot;2011年后：扩大管理范围&quot;">​</a></h3><ul><li>逐渐扩大管理范围</li><li>从单一选股到负责整个保险投资组合</li><li>承担更多战略性投资职责</li></ul><h2 id="与其他投资经理的关系" tabindex="-1">与其他投资经理的关系 <a class="header-anchor" href="#与其他投资经理的关系" aria-label="Permalink to &quot;与其他投资经理的关系&quot;">​</a></h2><ul><li>与<a href="/04_people/斯坦·利普西.html">斯坦·利普西</a>同为伯克希尔重要投资人才</li><li>与<a href="/04_people/卢·辛普森.html">卢·辛普森</a>在GEICO有传承关系</li><li>与<a href="/04_people/阿吉特·贾恩.html">阿吉特·贾恩</a>保持密切工作关系</li></ul><h2 id="巴菲特评价" tabindex="-1">巴菲特评价 <a class="header-anchor" href="#巴菲特评价" aria-label="Permalink to &quot;巴菲特评价&quot;">​</a></h2><p>巴菲特对康姆斯的评价：</p><ul><li>认可其独立的投资判断能力</li><li>赞赏其深入研究的工作方法</li><li>认为其为伯克希尔带来了新的投资视角</li></ul><hr><p><em>最后更新：2026-04-12</em></p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="./../02_公司/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a></li><li><a href="./沃伦·巴菲特.html">沃伦·巴菲特</a></li><li><a href="./阿吉特·贾恩.html">阿吉特·贾恩</a></li><li><a href="./卢·辛普森.html">卢·辛普森</a></li><li><a href="./斯坦·利普西.html">斯坦·利普西</a></li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=托德·康姆斯在2021年股东信中的原话">2021年：完整翻译|/01_letters/2021年/翻译</a></li></ul>',38)])])}const b=l(r,[["render",h]]);export{m as __pageData,b as default};
